     1	public class PressureWave : Wave
     2	{
     3		private new static GameObject prefab;
     4		private static ParticleSystemOverride _effectOverride;
     5		public bool useMaxHitCount = true;
     6		private int maxHitCount = 2;
     7		private int hitCounter;
     8		private ParticleSystem currentPartSys;
     9		public float minSpeed = 1.5f;
    10		public float maxSpeed = 2.5f;
    11		public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/PressureWave.prefab"));
    12		public static ParticleSystemOverride EffectOverride
    13		{
    14			get
    15			{
    16				if (_effectOverride == null)
    17				{
    18					ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
    19					particleSystemOverride.sortingLayer = "Shadow";
    20					particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.25f);
    21					_effectOverride = particleSystemOverride;
    22				}
    23				return _effectOverride;
    24			}
    25		}
    26		public override void Start()
    27		{
    28			base.Start();
    29			stopLayerMask = 0;
    30			ChaosStopwatch.Stop(spawnStopwatchID);
    31			if (useMaxHitCount)
    32			{
    33				for (int i = 0; i < wavePoolSize; i++)
    34				{
    35					Attack obj = wavePoolAttacks[i];
    36					obj.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(obj.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler
    37					Attack obj2 = wavePoolAttacks[i];
    38					obj2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(obj2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHand
    39				}
    40			}
    41		}
    42		public override void FixedUpdate()
    43		{
    44			if (!destroyQueued)
    45			{
    46				if (wavesElapsed >= maxWaveCount)
    47				{
    48					destroyQueued = true;
    49					destroyStopwatchID = ChaosStopwatch.Begin(destroyDelay);
    50					StopWave();
    51				}
    52				else if (ChaosStopwatch.Check(spawnStopwatchID))
    53				{
    54					spawnStopwatchID = ChaosStopwatch.Begin(spawnRate);
    55					ActivateWave();
    56				}
    57			}
    58		}
    59		public override void ActivateWave()
    60		{
    61			base.ActivateWave();
    62			calculatedSpacing = Mathf.Lerp(minSpeed, maxSpeed, (float)wavesElapsed / (float)maxWaveCount);
    63			currentPartSys = wavePoolTrans[waveCount].Find("DispersePartSys").GetComponent<ParticleSystem>();
    64			currentPartSys.Play();
    65			currentPartSys = wavePoolTrans[waveCount].Find("DropPartSys").GetComponent<ParticleSystem>();
    66			currentPartSys.Play();
    67			PoolManager.GetPoolItem<ParticleEffect>("SpinningAirBurst").Emit(1, wavePoolTrans[waveCount].position, EffectOverride);
    68			string audioID = "AirJet";
    69			Vector2? soundOrigin = activationPosition;
    70			float overridePitch = SoundManager.StandardPitchRange * 0.6f;
    71			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, overridePitch);
    72			if (wavesElapsed % 2 == 0)
    73			{
    74				audioID = "StandardSpinSingle";
    75				soundOrigin = activationPosition;
    76				overridePitch = SoundManager.StandardPitchRange * 0.6f;
    77				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.2f, overridePitch);
    78			}
    79		}
    80		public override void DestroyWave()
    81		{
    82			for (int i = 0; i < wavePoolSize; i++)
    83			{
    84				if (wavePoolAttacks[i] != null)
    85				{
    86					Attack obj = wavePoolAttacks[i];
    87					obj.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(obj.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler
    88				}
    89			}
    90			base.DestroyWave();
    91		}
    92		private void OnTargetHit(Collider2D col)
    93		{
    94			hitCounter++;
    95			if (hitCounter >= maxHitCount)
    96			{
    97				wavesElapsed = maxWaveCount;
    98			}
    99		}
   100	}
