     1	public class ProjectileHazard : MonoBehaviour
     2	{
     3		public enum FireType
     4		{
     5			Disable,
     6			OnTime,
     7			OnTrigger
     8		}
     9		public FireType fireType;
    10		public static Transform projectileHazardContainer;
    11		public string prefabPath = "Assets/Prefabs/Projectiles/ArrowHazard.prefab";
    12		private GameObject projectilePrefab;
    13		public string projectileSkillCategory = "EnemyScaled";
    14		public string projectileSkillID;
    15		public float attackChargeUpTime = 0.25f;
    16		private int chargeUpStopwatchID;
    17		public float initAttackCooldown;
    18		public float attackCooldown = 0.5f;
    19		private int attackStopwatchID = -1;
    20		private bool attackReady = true;
    21		public int shotCount = 1;
    22		public float shotDelay = 0.1f;
    23		private int shotDelayStopwatchID = -1;
    24		public float spreadModifier;
    25		private Vector3 spreadVector;
    26		private string targetTransName = "AllyHurtBox";
    27		public bool targetHurtBox = true;
    28		public bool targetTriggerCollider;
    29		public bool lockOnToTriggerCollider;
    30		public bool alwaysShowTargetLine;
    31		public bool showTargetLineOnChargeUp;
    32		private Transform targetPosTrans;
    33		private Vector3 originalTargetTransPos;
    34		private Vector3 targetPosition;
    35		private LineRenderer targetLine;
    36		public float targetLineWidth = 1f;
    37		public string shootAudioID = string.Empty;
    38		public string triggeredAudioID = string.Empty;
    39		private SpriteRenderer baseSprite;
    40		private SpriteRenderer downSprite;
    41		private SpriteRenderer rightSprite;
    42		private void Awake()
    43		{
    44			targetPosTrans = transform.Find("TargetPosition");
    45			targetLine = transform.Find("TargetLine").GetComponent<LineRenderer>();
    46			attackStopwatchID = ChaosStopwatch.Begin(initAttackCooldown);
    47			baseSprite = transform.Find("BaseSprite").GetComponent<SpriteRenderer>();
    48			downSprite = transform.Find("DownBaseSprite").GetComponent<SpriteRenderer>();
    49			rightSprite = transform.Find("RightBaseSprite").GetComponent<SpriteRenderer>();
    50		}
    51		private void Start()
    52		{
    53			if (projectileHazardContainer == null)
    54			{
    55				projectileHazardContainer = new GameObject().transform;
    56				projectileHazardContainer.gameObject.name = "FiredProjectilesContainer";
    57			}
    58			float num = Mathf.Clamp(targetLineWidth, 0.0625f, 9999f);
    59			targetLine.SetWidth(num, num);
    60			targetLine.sortingLayerName = "TargetLineAir";
    61			targetLine.enabled = alwaysShowTargetLine;
    62			projectilePrefab = ChaosBundle.Get(prefabPath);
    63			originalTargetTransPos = targetPosTrans.position;
    64			if (!targetHurtBox)
    65			{
    66				targetTransName = "AllyFloorContact";
    67			}
    68			baseSprite.enabled = false;
    69			Vector3 normalized = (targetPosTrans.position - transform.position).normalized;
    70			switch (Globals.GetPrimaryDirection(normalized))
    71			{
    72			case FacingDirection.Down:
    73				downSprite.enabled = true;
    74				break;
    75			case FacingDirection.Right:
    76				rightSprite.enabled = true;
    77				break;
