		HandleSpeedUp();
		if (TargetExists)
		{
			HandleHomingMovement();
		}
	}
	public virtual void HandleSpeedUp()
	{
		if (moveSpeed < baseMoveSpeed)
		{
			moveSpeed += Time.fixedDeltaTime;
		}
	}
	public virtual void HandleHomingMovement()
	{
		timePercentage = durationStopwatch.TimePercentage;
		homingCompleted = timePercentage >= 1f;
		calcBias = Mathf.Lerp(1f, homingBias, 2f * ((!(timePercentage < 0.5f)) ? (1f - timePercentage) : timePercentage));
		targetVector = (targetTrans.position - transform.position).normalized;
		prevVector = moveVector;
		moveVector = (moveVector + targetVector * calcBias * Time.fixedDeltaTime).normalized;
		attackBox.knockbackOverwriteVector = moveVector;
		moveSpeedLerpValue = Vector2.Angle(prevVector, moveVector) * 0.00555f;
