	private void FixedUpdate()
	{
		if (atkCompleted)
		{
			return;
		}
		if (!atkStarted)
		{
			if (ChaosStopwatch.Check(atkStopwatchID))
			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, attackInterval, attackCount);
				frontPartSys.Play();
				frontPartSys2.Play();
				backPartSys.Play();
			}
			return;
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Running:
