	public void EmitTrail(Vector2 startPos, Vector2 endPos, int givenParticleCount = 0)
	{
		float num = Vector2.Distance(startPos, endPos);
		float num2 = num * 0.5f;
		particleCount = ((givenParticleCount <= 0) ? Mathf.Clamp((int)(num * 2f), 3, 50) : givenParticleCount);
		Vector3 position = new Vector3((startPos.x + endPos.x) * 0.5f, (startPos.y + endPos.y) * 0.5f, 0f);
		Vector3 vectorA = new Vector3(startPos.x + num2, startPos.y);
		float z = 360f - Globals.Vector3AngleWithPivot(vectorA, startPos, endPos);
		transform.position = position;
		transform.localScale = new Vector3(num2, transform.localScale.y, transform.localScale.z);
		transform.localEulerAngles = new Vector3(transform.localEulerAngles.x, transform.localEulerAngles.y, z);
		trailEmitter.startRotation = 0f - (float)Math.PI / 180f * transform.localEulerAngles.z;
		trailEmitter.Emit(particleCount);
		trailEmitted = true;
		destroyStopwatchID = ChaosStopwatch.Begin(trailEmitter.duration);
	}
	private void Update()
	{
		if (trailEmitted && destroyAfterEffect && ChaosStopwatch.Check(destroyStopwatchID))
		{
			UnityEngine.Object.Destroy(gameObject);
