		{
			transform.position = followTrans.position;
		}
		if (released && !hitComplete && lastPosition != transform.position)
		{
			offsetVector = transform.position - lastPosition;
			foreach (Entity item in entitySet)
			{
				if (!(item == null) && !(item.rigidbody2D == null))
				{
					item.rigidbody2D.MovePosition(item.transform.position + offsetVector);
