	private bool atkCompleted;
	private bool spinRandomized;
	private void Start()
	{
		atkStopwatchID = ChaosStopwatch.Begin(atkInterval, useInterval: true, atkInterval, 12);
		movement.InitOrbitAngle(orbitInitVec, clockwise: false);
		anim.Play("Spawn", -1, 0f);
