		if (useOrbit && orbitTrans != null)
		{
			movement.OrbitTarget(orbitTrans.position);
		}
		if (atkCompleted)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Running:
			attackCol.enabled = true;
			break;
		case StopwatchState.Ready:
			attackCol.enabled = false;
			break;
		case StopwatchState.Done:
			if (useOrbit)
			{
				useOrbit = false;
				movement.orbit = false;
				floorCol.enabled = true;
				atkStopwatchID = ChaosStopwatch.Begin(atkInterval, useInterval: true, atkInterval, 10);
				attack.ChangeAttackInfoLevel(2);
