		timeStopwatch.SetDelay(flyTime * 0.95f, stopCurrent: false, autoStart: true);
		PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position, moveVector);
	}
	public override bool CheckMaxLifeTime()
	{
		if (base.CheckMaxLifeTime())
		{
			targetHit = true;
			ResetProjectile();
			return true;
		}
		return false;
	}
	public override void ResetProjectile()
	{
		if (targetHit || reTargetCompleted || timeStopwatch.IsRunning)
		{
			base.ResetProjectile();
		}
		else if (!reTarget)
		{
			reTarget = true;
			speedStopwatch.IsRunning = true;
		}
	}
	public override void HandleSpeedUp()
	{
		if (!reTarget)
		{
			return;
		}
		if (reTargetCompleted)
		{
			moveSpeed = Mathf.Lerp(0f, baseMoveSpeed, speedStopwatch.TimePercentage);
			if (!reTargetEffectPlayed && moveSpeed > 8f)
			{
				PoolManager.GetPoolItem<ParticleEffect>("WindBallSmallEffect").Emit(5, transform.position + (Vector3)moveVector, ParticleEffectOverrides.RadiusZero);
				PoolManager.GetPoolItem<DashAirBurst>().Burst(transform.position + (Vector3)moveVector * 0.5f, moveVector);
				rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
				reTargetEffectPlayed = true;
			}
			return;
		}
		moveSpeed = Mathf.Lerp(baseMoveSpeed, 0f, speedStopwatch.TimePercentage);
		if (moveSpeed <= 0f)
		{
			reTargetCompleted = true;
			speedStopwatch.IsRunning = true;
			if (targetTrans != null && Vector2.SqrMagnitude(targetTrans.position - transform.position) < 100f)
			{
				moveVector = (targetTrans.position - transform.position).normalized;
			}
			attackBox.knockbackOverwriteVector = moveVector;
			flyTime = 2f;
			RefreshFlightTime();
			baseMoveSpeed *= 1.5f;
			string audioID = "StandardSpin";
			Transform originTrans = transform;
		}
		if (!spinSpeedModified && moveSpeed < 4f)
		{
			rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f * 2f);
			spinSpeedModified = true;
		}
	}
	private void OnTargetHit(Collider2D givenCol)
	{
		targetHit = true;
	}
